@lru_cache(maxsize=16)
def logo_pixmap(color: str = "#355872", height: int = 36, dpr: float = 2.0) -> QPixmap:
    """Render the logo mark in a single colour at the given height."""
    vw, vh = _VIEWBOX
    width = round(height * vw / vh)
    svg = (
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {vw} {vh}">'
        f'<path fill="{color}" fill-rule="evenodd" d="{_PATH}"/></svg>'
    )
    renderer = QSvgRenderer(QByteArray(svg.encode()))
    pm = QPixmap(int(width * dpr), int(height * dpr))
    pm.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pm)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    renderer.render(painter, QRectF(0, 0, width * dpr, height * dpr))
    painter.end()
    pm.setDevicePixelRatio(dpr)
    return pm
